   798				// the exact path doesn't exist on disk.
   799				if (await searchAndOpen(p, raw, line, column)) {
   800					return;
   801				}
   802			}
   803	
   804			// Nothing matched: report the failure (error reports are allowed;
   805			// success notifications are not).
   806			void vscode.window.showWarningMessage(
   807				`CodePi: no file, folder or URL matches “${raw}”`,
   808			);
   809		} catch (err) {
