   553	/**
   554	 * Sync the editor review state with the TUI filechanges tracker.
   555	 *
   556	 * The filechanges extension appends `filechanges:resolved` custom session
   557	 * entries when the user runs /filechanges-accept or /filechanges-decline in
   558	 * the TUI. This poll picks them up and resolves the matching review proposals
   559	 * so editor decorations / the review bar clear in step with the TUI.
   560	 */
   561	async function pollFileChangesSync(state: SessionState): Promise<void> {
   562		if (!state.sessionManager) return;
   563		let branch: any[];
   564		try {
   565			branch = state.sessionManager.getBranch();
   566		} catch {
   567			return;
   568		}
   569		if (branch.length === 0) return;
   570		const headId = branch[branch.length - 1].id;
   571		if (headId === state.fcLastHead) return;
   572		state.fcLastHead = headId;
   573	
   574		let changed = false;
   575		for (const entry of branch) {
   576			if (
   577				entry.type !== "custom" ||
   578				entry.customType !== "filechanges:resolved"
   579			) {
   580				continue;
   581			}
   582			if (state.fcSeenEntries.has(entry.id)) continue;
   583			state.fcSeenEntries.add(entry.id);
   584			const data = entry.data as
   585				| { paths?: string[]; reason?: "accept" | "decline" }
   586				| undefined;
   587			if (!data?.paths) continue;
   588			for (const p of data.paths) {
   589				const proposal = state.review.getProposalByFile(
   590					resolveReviewUri(p).toString(),
   591				);
   592				if (!proposal) continue;
   593				changed = true;
   594				await state.review.resolveFile(
   595					proposal.proposalId,
   596					data.reason === "decline" ? "rejected" : "accepted",
   597				);
   598			}
   599		}
   600		if (changed) {
   601			updateReviewStatusBar();
   602		}
   603	}
