   605	/** Relativize a proposal uri for the TUI tracker (its cwd is the workspace). */
   606	function toRelPath(uriStr: string): string {
   607		try {
   608			const uri = vscode.Uri.parse(uriStr);
   609			const folder = vscode.workspace.getWorkspaceFolder(uri);
   610			if (folder) {
   611				return (
   612					path.relative(folder.uri.fsPath, uri.fsPath) ||
   613					path.basename(uri.fsPath)
   614				);
   615			}
   616			return uri.fsPath;
   617		} catch {
   618			return uriStr;
   619		}
   620	}
