   622	/** Resolve a tracker path (relative to the workspace, or absolute) to a uri. */
   623	function resolveReviewUri(p: string): vscode.Uri {
   624		if (path.isAbsolute(p)) return vscode.Uri.file(p);
   625		const ws = vscode.workspace.workspaceFolders?.[0];
   626		if (ws) return vscode.Uri.joinPath(ws.uri, p);
   627		return vscode.Uri.file(p);
   628	}
