   722	/**
   723	 * Resolve a session id to its JSONL file path, used when restoring a TUI tab
   724	 * after a window reload. Prefers sessions under the current workspace root;
   725	 * falls back to a full scan (covers sessions from other folders).
   726	 */
   727	async function findSessionPathById(
   728		sessionId: string,
   729	): Promise<string | undefined> {
   730		try {
   731			const pi = await getPi();
   732			const byCwd: any[] = await pi.SessionManager.list(
   733				getWorkspaceRoot(),
   734				getCodePiSessionDirForRuntime(),
   735			);
   736			const hit = byCwd.find((s: any) => s.id === sessionId);
   737			if (hit) return hit.path;
   738			const all: any[] = await pi.SessionManager.listAll(
   739				getCodePiSessionDirForRuntime(),
   740			);
   741			return all.find((s: any) => s.id === sessionId)?.path;
   742		} catch {
   743			return undefined;
   744		}
   745	}
