   749	/**
   750	 * Open a Ctrl+clicked terminal link (VS Code built-in terminal behavior):
   751	 * URLs go to the default browser via openExternal, file paths open in the
   752	 * editor at the (optional) line:column — mirroring TerminalUrlLinkOpener and
   753	 * TerminalLocalFileLinkOpener from the vscode-main submodule.
   754	 */
   755	async function openTerminalLink(link: CodePiOpenLinkPayload): Promise<void> {
   756		try {
   757			const raw = (link.text ?? "").trim();
   758			if (!raw) return;
   759	
   760			const workspaceRoot = getWorkspaceRoot();
   761			const folders =
   762				vscode.workspace.workspaceFolders?.map((f) => f.uri.fsPath) ?? [];
   763	
   764			// OSC 8 hyperlinks carry an explicit target.
   765			if (link.kind === "url" && link.url) {
   766				await openUrlOrFile(link.url);
   767				return;
   768			}
   769			if (link.kind === "file" && link.path) {
   770				const resolved = resolveTerminalFilePath(
   771					link.path,
   772					workspaceRoot,
   773					folders,
   774				);
   775				if (resolved) {
   776					await openTerminalFile(resolved, link.line, link.column);
   777					return;
   778				}
   779			}
   780	
   781			// Word link: VS Code decides what it is on activation (URL → browser,
   782			// existing file → editor, directory → explorer, otherwise → search).
   783			const url = classifyAsUrl(raw);
   784			if (url) {
   785				await openUrlOrFile(raw);
   786				return;
   787			}
   788	
   789			const normalized = normalizeSearchText(raw);
   790			const { path: p, line, column } = splitLineColumn(normalized);
   791			if (p) {
   792				const resolved = resolveTerminalFilePath(p, workspaceRoot, folders);
   793				if (resolved) {
   794					await openTerminalFile(resolved, line, column);
   795					return;
   796				}
   797				// Fallback like TerminalSearchLinkOpener: search the workspace when
   798				// the exact path doesn't exist on disk.
   799				if (await searchAndOpen(p, raw, line, column)) {
   800					return;
   801				}
   802			}
   803	
   804			// Nothing matched: report the failure (error reports are allowed;
   805			// success notifications are not).
   806			void vscode.window.showWarningMessage(
   807				`CodePi: no file, folder or URL matches “${raw}”`,
   808			);
   809		} catch (err) {
   810			void vscode.window.showErrorMessage(
   811				`CodePi: could not open link — ${
   812					err instanceof Error ? err.message : String(err)
   813				}`,
   814			);
   815		}
   816	}
