   818	/** Open a URL externally, or a file:// target in the editor. */
   819	async function openUrlOrFile(urlText: string): Promise<void> {
   820		const uri = vscode.Uri.parse(urlText);
   821		if (uri.scheme === "file") {
   822			await openTerminalFile(uri.fsPath);
   823			return;
   824		}
   825		await vscode.env.openExternal(uri);
