   828	/**
   829	 * Workspace search fallback for a word that isn't an existing path: open the
   830	 * single exact match directly (VS Code's _getExactMatch), otherwise open the
   831	 * Quick Open file picker (Ctrl+P) pre-filled with the word — the on-top menu
   832	 * VS Code's terminal word links use (quickAccess), NOT the sidebar search.
   833	 */
   834	async function searchAndOpen(
   835		pathText: string,
   836		query: string,
   837		line?: number,
   838		column?: number,
   839	): Promise<boolean> {
   840		const glob = escapeGlob(pathText);
   841	
   842		// Exact relative-path match.
   843		const exact = await vscode.workspace.findFiles(
   844			`**/${glob}`,
   845			"**/node_modules/**",
   846			5,
   847		);
   848		if (exact.length === 1) {
   849			await openTerminalFile(exact[0].fsPath, line, column);
   850			return true;
   851		}
   852	
   853		// Filename contains the word (quick access-style matching).
   854		const found = await vscode.workspace.findFiles(
   855			`**/*${glob}*`,
   856			"**/node_modules/**",
   857			10,
   858		);
   859		if (found.length === 1) {
   860			await openTerminalFile(found[0].fsPath, line, column);
   861			return true;
   862		}
   863	
   864		// Open the Ctrl+P file picker pre-filled with the word; its own fuzzy
   865		// file search lists any matches.
   866		await vscode.commands.executeCommand(
   867			"workbench.action.quickOpen",
   868			query || pathText,
   869		);
   870		return true;
